ruleToc.nextTocUrl:
@js:
var d=JSON.parse(result);
var meta=d.meta||{};
var np=meta.next_page;
if(np){
  var base=baseUrl.replace(/[?&]page=\d+/,'');
  (base.indexOf('?')>=0 ? base+'&page='+np : base+'?page='+np);
}else{''};

